// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        vm.assume(_data.length > 0);
        FalseAccepter helper = new FalseAccepter();
        address target = address(helper);
        bool ok;
        try c.forward(target, _data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract FalseAccepter {
    fallback(bytes calldata _input) external payable returns (bytes memory) {
        require(_input.length == 0, "Accepts only empty calldata");
        return "";
    }
}
